import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, displacement } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry (tessellated plane)
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Base material (machined‑metal look)
  const material = new MeshStandardNodeMaterial({
    color: 0xffffff,
    metalness: 0.3,
    roughness: 0.6,
    clearcoat: 0.1,
  });

  // Placeholder nodes (will be replaced once textures load)
  material.mapNode = null;
  material.displacementNode = null;

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load color texture
  const texturePromises = [];

  if (config.imageUrl) {
    const texPromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.mapNode = texture(tex);
      material.needsUpdate = true;
    });
    texturePromises.push(texPromise);
  }

  // Load depth map for displacement
  if (config.depthMapUrl) {
    const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      material.displacementNode = displacement(texture(tex), 0.1);
      material.needsUpdate = true;
    });
    texturePromises.push(depthPromise);
  }

  // Apply cinematic primitives from config
  const primitiveRefs = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const p of config.cinematicPrimitives) {
      const prim = ctx.primitives[p.name](root, p.params);
      primitiveRefs.push(prim);
    }
  }

  // Event handlers (hover lift, click emit)
  const hoverTL = { value: null };
  root.userData.handlers = {
    hover: {
      onEnter: () => {
        if (hoverTL.value) hoverTL.value.kill();
        hoverTL.value = gsap.timeline();
        hoverTL.value.to(root.position, {
          y: root.position.y + 0.15,
          duration: 0.3,
          ease: 'power3.out',
        });
      },
      onLeave: () => {
        if (hoverTL.value) {
          hoverTL.value.to(root.position, {
            y: root.position.y - 0.15,
            duration: 0.3,
            ease: 'power3.out',
          });
          hoverTL.value = null;
        }
      },
    },
    click: {
      onClick: () => {
        ctx.emit('hub-features.select', {});
      },
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded textures if they exist
    texturePromises.forEach((p) => {
      p.then((tex) => {
        if (tex && typeof tex.dispose === 'function') tex.dispose();
      });
    });

    // Kill GSAP timelines
    if (hoverTL.value) hoverTL.value.kill();

    // Cleanup primitives
    primitiveRefs.forEach((ref) => {
      if (ref && typeof ref.cleanup === 'function') ref.cleanup();
    });
  };

  return root;
}
